<template>
<div>
    <div style="padding: 10px 0;text-align: right" >
        <el-input style="width: 500px" placeholder="请输入名称/邮箱/电话/地址" suffix-icon="el-icon-search" v-model="username"></el-input>
        <el-button class="ml-5" type="primary" @click="load">搜索</el-button>
        <el-button  type="warning" @click="reset">重置</el-button>
    </div>
    <div style="padding: 10px 0">

        <el-button type="primary" @click="handleAdd">新增<i class="el-icon-circle-plus-outline"></i></el-button>
        <el-popconfirm
                class="ml-5"
                confirm-button-text='确定'
                cancel-button-text='我在想想'
                icon="el-icon-info"
                icon-color="red"
                title="您确定删除吗？"
                @confirm="deleteBatch"
        >
            <el-button type="danger" slot="reference">批量删除<i class="el-icon-remove-outline"></i></el-button>
        </el-popconfirm>
    </div>
    <el-table :data="tableData" style="width: 100%" border stripe :header-cell-class-name="'headerBg'" @selection-change="handleSelectionChange">
        <el-table-column type="selection" width="55"></el-table-column>
        <el-table-column prop="id" label="序号" width="150" align="center"></el-table-column>
        <el-table-column prop="username" label="用户名" width="150" align="center"></el-table-column>
        <el-table-column prop="role" label="角色" width="150" align="center">
        <template slot-scope="scope">
            <el-tag type="primary" v-if="scope.row.role === 'ROLE_ADMIN'">管理员</el-tag>
            <el-tag type="warning" v-if="scope.row.role === 'ROLE_MEMBER'">普通成员</el-tag>
        </template>
        </el-table-column>
        <el-table-column prop="nickname" label="昵称" width="150" align="center"></el-table-column>
        <el-table-column prop="email" label="邮箱" width="150" align="center"></el-table-column>
        <el-table-column prop="telephone" label="电话" width="150" align="center"></el-table-column>
        <el-table-column prop="address" label="地址" width="150" align="center"></el-table-column>

        <el-table-column prop="operation" label="操作"width="300" align="center">
            <template slot-scope="scope">
                <el-button type="success" @click="handleEdit(scope.row)">编辑 <i class="el-icon-edit"></i></el-button>
                <el-popconfirm
                        class="ml-5"
                        confirm-button-text='好的'
                        cancel-button-text='我在想想'
                        icon="el-icon-info"
                        icon-color="red"
                        title="您确定删除吗？"
                        @confirm="handleDelete(scope.row.id)"
                >
                    <el-button type="danger" slot="reference" >删除<i class="el-icon-remove-outline"></i></el-button>
                </el-popconfirm>
            </template>
        </el-table-column>
    </el-table>
    <!--分页 选页面-->
    <div style="padding: 10px 0">
        <el-pagination
                @size-change="handleSizeChange"
                @current-change="handleCurrentChange"
                :current-page="pageNum"
                :page-sizes="[2, 5, 10, 20]"
                :page-size="pageSize"
                layout="total, sizes, prev, pager, next, jumper"
                :total="total">
        </el-pagination>
    </div>
    <el-dialog title="新增用户信息" :visible.sync="dialogFormVisible" width="30%">
        <el-form label-width="80px" size="small" >
            <el-form-item label="用户名">
                <el-input v-model="form.username" autocomplete="off"></el-input>
            </el-form-item>
            <el-form-item label="角色">
                <el-select clearable v-model="form.role" placeholder="请选择角色" style="width: 100%">
                    <el-option v-for="item in roles" :key="item.name" :label="item.name" :value="item.flag"></el-option>
                </el-select>
            </el-form-item>
            <el-form-item label="昵称">
                <el-input v-model="form.nickname" autocomplete="off"></el-input>
            </el-form-item>
            <el-form-item label="邮箱">
                <el-input v-model="form.email" autocomplete="off"></el-input>
            </el-form-item>
            <el-form-item label="电话">
                <el-input v-model="form.telephone" autocomplete="off"></el-input>
            </el-form-item>
            <el-form-item label="地址">
                <el-input v-model="form.address" autocomplete="off"></el-input>
            </el-form-item>
        </el-form>
        <div slot="footer" class="dialog-footer">
            <el-button @click="dialogFormVisible = false">取 消</el-button>
            <el-button type="primary" @click="save">确 定</el-button>
        </div>
    </el-dialog>
</div>
</template>

<script>
    import {serverIp} from "../../public/config";

    export default {
        name: "User",
        data(){
            return{
                serverIp: serverIp,
                tableData: [],
                total: 0,
                pageNum: 1,
                pageSize: 10,
                // integration: "",
                username:"",
                form: {},
                dialogFormVisible: false,
                multipleSelection: [],
                roles: [],
                courses: [],
                vis: false,
                stuCourses: [],
                stuVis: false
            }
        },
        created() {
            //请求分页查询数据
            this.load()
        },
        methods:{
            lookCourse(courses) {
                this.courses = courses
                this.vis = true
            },
            lookStuCourse(stuCourses) {
                this.stuCourses = stuCourses
                this.stuVis = true
            },
            load(){
                /*fetch请求分页查询*/
                // fetch("http://localhost:8888/user/page?pageNum="+this.pageNum+ "&pageSize="+ this.pageSize+ "&integration=" + this.integration ).then(res => res.json()).then(res =>{
                //     (res)
                //     this.tableData =res.data
                //     this.total=res.total
                // })
                /*Axios请求分页查询*/
                this.request.get("/user/page", {
                    params: {
                        pageNum: this.pageNum,
                        pageSize: this.pageSize,
                        username: this.username
                    }
                }).then(res => {
                    (res)
                    this.tableData = res.data.records
                    this.total = res.data.total

                })
                this.request.get("/role").then(res => {
                    this.roles = res.data
                })
            },
            save(){
                this.request.post("/user/save",this.form).then( res =>{
                    if (res.code === '200'){
                        this.$message.success("保存成功")
                        this.dialogFormVisible = false
                        this.load()
                    }else {
                        this.$message.error("保存失败")
                    }
                })

            },
            reset(){
                this.username=""
                this.load()
            },
            handleSelectionChange(val){//删除确认提醒框
                (val)
                this.multipleSelection = val
            },
            deleteBatch(){
                let ids =  this.multipleSelection.map(v => v.id)// 因为后端的是List数组 而这ids是对象数组 所以要用前端的map(v => v.id)把对象数组 [{},{},{}] 转变成纯id的数组 [1,2,3,...]
                this.request.post("/user/del/batch/",ids).then(res => {
                    if(res.code === '200'){
                        this.$message.success("批量删除成功")
                        this.load()
                    }else {
                        this.$message.error("批量删除失败")
                    }
                })
            },
            handleEdit(row){
                this.form = JSON.parse(JSON.stringify(row))
                this.dialogFormVisible = true
            },
            handleDelete(id){
                this.request.delete("/user/" + id).then(res => {
                    if (res.code === '200'){
                        this.$message.success("删除成功")
                        this.load()
                    }else {
                        this.$message.error("删除失败")
                    }
                })
            },
            handleAdd(){
                this.dialogFormVisible=true
                this.form={}
            },
            handleSizeChange(pageSize){
                (pageSize)
                this.pageSize = pageSize
                this.load()
            },
            handleCurrentChange(pageNum){
                (pageNum)
                this.pageNum = pageNum
                this.load()
            },
            exp(){
                window.open(`http://${serverIp}:8888/user/export`)
            },
            handleExcelImportSuccess(){
                this.$message.success("导入上传成功")
                this.load()
            }

        }
    }
</script>

<style>
    .headerBg{
        background:#eee!important;

    }
</style>
